'use strict';
/* SUMO CAT! — 8-bit knockback arena brawler. Player + 3 bots, last cat on the dohyo wins. */
const W = 480, H = 270;
const cv = document.getElementById('cv'), ctx = cv.getContext('2d');
ctx.imageSmoothingEnabled = false;
const AUTO = new URLSearchParams(location.search).get('auto') === '1';
const RING = { x: 240, y: 150, r: 96 };
const CAT_R = 13;

/* ---------- assets ---------- */
const SHEET_B64 = "";
const BG_B64 = "";
const MANIFEST = {"ready": [0, 0, 273, 266], "charge": [277, 55, 264, 211], "shove": [550, 23, 264, 243], "spin": [824, 2, 262, 264], "stomp": [38, 286, 197, 246], "hit": [295, 289, 228, 243], "dizzy": [552, 281, 260, 251], "victory": [830, 277, 250, 255]};
let sheetImg = null, bgImg = null, tinted = {};
function loadAssets() {
  return new Promise((resolve) => {
    let n = 0;
    const done = () => { if (++n === 2) { makeTints(); resolve(); } };
    sheetImg = new Image();
    sheetImg.onload = done;
    sheetImg.src = 'data:image/png;base64,' + SHEET_B64;
    bgImg = new Image();
    bgImg.onload = done;
    bgImg.src = 'data:image/jpeg;base64,' + BG_B64;
  });
}
// pre-tinted variants so bots read as different cats: [saturate, brightness, hueRotate]
const TINTS = [
  null,                       // P0 player: original orange
  'saturate(0.25) brightness(1.25)',   // P1: gray-white
  'saturate(1.4) hue-rotate(-35deg) brightness(0.75)', // P2: dark brown/red
  'saturate(0.7) hue-rotate(40deg) brightness(1.1)',    // P3: cream/gold
];
function makeTints() {
  for (let i = 0; i < 4; i++) {
    const c = document.createElement('canvas');
    c.width = sheetImg.width; c.height = sheetImg.height;
    const g = c.getContext('2d');
    try {
      if (TINTS[i]) g.filter = TINTS[i];
      g.drawImage(sheetImg, 0, 0);
      g.filter = 'none';
    } catch (e) { g.drawImage(sheetImg, 0, 0); }
    tinted[i] = c;
  }
}
function drawPose(g, pose, x, y, flip, tintIdx, scale) {
  const f = MANIFEST[pose]; if (!f) return;
  const img = tinted[tintIdx] || sheetImg;
  g.save();
  g.translate(Math.round(x), Math.round(y));
  if (flip) g.scale(-1, 1);
  if (scale && scale !== 1) g.scale(scale, scale);
  g.drawImage(img, f[0], f[1], f[2], f[3], -f[2] / 2, -f[3] + 8, f[2], f[3]);
  g.restore();
}

/* ---------- audio : chiptune ---------- */
let AC = null, noiseBuf = null;
function audio() {
  if (!AC) {
    AC = new (window.AudioContext || window.webkitAudioContext)();
    noiseBuf = AC.createBuffer(1, AC.sampleRate, AC.sampleRate);
    const d = noiseBuf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    startMusic();
  }
  if (AC.state === 'suspended') AC.resume();
}
function env(g, t, a, peak, dec) {
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(peak, t + a);
  g.gain.exponentialRampToValueAtTime(0.0001, t + a + dec);
}
function tone(freq, freqEnd, dur, type, vol) {
  if (!AC) return;
  const t = AC.currentTime, o = AC.createOscillator(), g = AC.createGain();
  o.type = type; o.frequency.setValueAtTime(freq, t);
  if (freqEnd) o.frequency.exponentialRampToValueAtTime(Math.max(1, freqEnd), t + dur);
  env(g, t, 0.005, vol || 0.2, dur);
  o.connect(g); g.connect(AC.destination);
  o.start(t); o.stop(t + dur + 0.05);
}
function noise(dur, vol, filterFreq, type) {
  if (!AC) return;
  const t = AC.currentTime, s = AC.createBufferSource(), g = AC.createGain(), f = AC.createBiquadFilter();
  s.buffer = noiseBuf; s.loop = true;
  f.type = type || 'lowpass'; f.frequency.value = filterFreq || 800;
  env(g, t, 0.005, vol || 0.25, dur);
  s.connect(f); f.connect(g); g.connect(AC.destination);
  s.start(t); s.stop(t + dur + 0.05);
}
const SFX = {
  thump(p) { tone(130, 38, 0.22, 'sine', 0.35); noise(0.08, 0.18, 500); },
  whiff() { noise(0.09, 0.08, 2500, 'highpass'); },
  dash() { noise(0.12, 0.12, 1200); },
  whistle() { tone(1800, 3400, 0.55, 'sine', 0.22); },
  drum() { tone(95, 34, 0.28, 'sine', 0.4); },
  hit() { tone(220, 90, 0.12, 'square', 0.16); noise(0.06, 0.12, 1800); },
  cheer() {
    if (!AC) return;
    const t = AC.currentTime, s = AC.createBufferSource(), g = AC.createGain(), f = AC.createBiquadFilter();
    s.buffer = noiseBuf; s.loop = true; f.type = 'bandpass'; f.frequency.value = 1200; f.Q.value = 0.8;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.3, t + 0.25);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.4);
    s.connect(f); f.connect(g); g.connect(AC.destination);
    s.start(t); s.stop(t + 1.5);
  },
  countTick() { tone(660, 660, 0.07, 'square', 0.14); },
  go() { tone(523, 523, 0.09, 'square', 0.16); setTimeout(() => tone(784, 784, 0.16, 'square', 0.16), 90); },
};
// pentatonic loop: taiko-ish bass + lead
const BASSLINE = [0, -1, -1, 0, -1, -1, 0, -1, -1, 0, -1, 3, -1, -1, 2, -1]; // semitone offsets from A1, -1 = rest
const LEAD = [12, -1, 15, -1, 17, -1, 15, 12, -1, 10, 12, -1, 15, 17, 19, -1,
              19, -1, 17, 15, -1, 12, -1, 10, 12, -1, -1, -1, 7, -1, 10, -1];
function startMusic() {
  const stepDur = 60 / 132 / 2; let step = 0, nextT = AC.currentTime + 0.1;
  const base = 110; // A1
  setInterval(() => {
    if (!AC || document.hidden) { nextT = Math.max(nextT, AC ? AC.currentTime + 0.1 : 0); return; }
    while (nextT < AC.currentTime + 0.25) {
      const b = BASSLINE[step % BASSLINE.length];
      if (b >= 0 && AC) {
        const t = nextT, o = AC.createOscillator(), g = AC.createGain();
        o.type = 'sine';
        o.frequency.setValueAtTime(base * Math.pow(2, b / 12), t);
        o.frequency.exponentialRampToValueAtTime(34, t + 0.22);
        env(g, t, 0.004, 0.32, 0.22);
        o.connect(g); g.connect(AC.destination); o.start(t); o.stop(t + 0.3);
      }
      const l = LEAD[step % LEAD.length];
      if (l >= 0 && AC) {
        const t = nextT, o = AC.createOscillator(), g = AC.createGain();
        o.type = 'square';
        o.frequency.value = 220 * Math.pow(2, l / 12);
        env(g, t, 0.004, 0.055, 0.16);
        o.connect(g); g.connect(AC.destination); o.start(t); o.stop(t + 0.22);
      }
      nextT += stepDur; step++;
    }
  }, 90);
}

/* ---------- input : keyboard + touch ---------- */
const keys = {};
addEventListener('keydown', e => { keys[e.code] = true; audio(); if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)) e.preventDefault(); });
addEventListener('keyup', e => { keys[e.code] = false; });
addEventListener('pointerdown', audio, { once: true });
// touch overlay (gamepress TOUCH.md standard)
const TOUCH_ON = ('ontouchstart' in window);
const touchUI = document.getElementById('touch-ui');
const stickBase = document.getElementById('stick-base'), stickKnob = document.getElementById('stick-knob');
const btnA = document.getElementById('btn-a'), btnB = document.getElementById('btn-b');
const touch = { sx: 0, sy: 0, dx: 0, dy: 0, active: false, id: null, a: false, b: false, aId: null, bId: null };
if (TOUCH_ON) {
  touchUI.style.display = 'block';
  const R = 56, DZ = 0.18;
  addEventListener('pointerdown', e => {
    if (e.pointerType === 'mouse') return;
    audio();
    if (e.clientX < innerWidth / 2 && touch.id === null && !(e.target.classList && e.target.classList.contains('tbtn'))) {
      touch.id = e.pointerId; touch.sx = e.clientX; touch.sy = e.clientY;
      touch.dx = 0; touch.dy = 0; touch.active = true;
      stickBase.style.display = stickKnob.style.display = 'block';
      stickBase.style.left = (e.clientX - 55) + 'px'; stickBase.style.top = (e.clientY - 55) + 'px';
      stickKnob.style.left = (e.clientX - 26) + 'px'; stickKnob.style.top = (e.clientY - 26) + 'px';
    }
  });
  addEventListener('pointermove', e => {
    if (e.pointerId === touch.id && touch.active) {
      let dx = e.clientX - touch.sx, dy = e.clientY - touch.sy;
      const d = Math.hypot(dx, dy);
      if (d > R) { dx = dx / d * R; dy = dy / d * R; }
      touch.dx = dx / R; touch.dy = dy / R;
      if (Math.hypot(touch.dx, touch.dy) < DZ) { touch.dx = 0; touch.dy = 0; }
      stickKnob.style.left = (touch.sx + dx - 26) + 'px';
      stickKnob.style.top = (touch.sy + dy - 26) + 'px';
    }
  });
  const endTouch = e => {
    if (e.pointerId === touch.id) {
      touch.id = null; touch.active = false; touch.dx = touch.dy = 0;
      stickBase.style.display = stickKnob.style.display = 'none';
    }
    if (e.pointerId === touch.aId) { touch.a = false; touch.aId = null; btnA.classList.remove('on'); }
    if (e.pointerId === touch.bId) { touch.b = false; touch.bId = null; btnB.classList.remove('on'); }
  };
  addEventListener('pointerup', endTouch);
  addEventListener('pointercancel', endTouch);
  const bindBtn = (el, key) => {
    el.addEventListener('pointerdown', e => {
      e.preventDefault(); audio();
      touch[key] = true; touch[key + 'Id'] = e.pointerId; el.classList.add('on');
    });
  };
  bindBtn(btnA, 'a'); bindBtn(btnB, 'b');
}
function pressed(code) { return !!keys[code]; }
function inLeft()  { return pressed('ArrowLeft') || pressed('KeyA') || touch.dx < -0.35; }
function inRight() { return pressed('ArrowRight') || pressed('KeyD') || touch.dx > 0.35; }
function inUp()    { return pressed('ArrowUp') || pressed('KeyW') || touch.dy < -0.45; }
function inDown()  { return pressed('ArrowDown') || pressed('KeyS') || touch.dy > 0.45; }
function inShove() { return pressed('KeyZ') || pressed('KeyJ') || touch.a; }
function inSpin()  { return pressed('KeyX') || pressed('KeyK') || pressed('Space') || touch.b; }

/* ---------- game state ---------- */
const NAMES = ['YOU', 'TORA', 'KURO', 'MOCHI'];
const WIN_PAWS = 3; // best of 5
let cats = [], parts = [], bursts = [];
let phase = 'title'; // title | countdown | fight | roundEnd | matchEnd
let phaseT = 0, roundNum = 1, hitstop = 0, winner = -1, champ = -1;
let announce = '', announceT = 0, subAnnounce = '';

function mkCat(i, bot) {
  const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
  return {
    idx: i, name: NAMES[i], bot: bot || AUTO,
    x: RING.x + Math.cos(a) * 52, y: RING.y + Math.sin(a) * 40,
    vx: 0, vy: 0, face: Math.cos(a) > 0 ? -1 : 1,
    wobble: 0, alive: true, deadT: 0,
    pose: 'ready', poseT: 0, flash: 0, wobT: 0,
    charging: false, chargeT: 0, shoveCD: 0,
    spinCD: 0, spinning: 0, spinDX: 0, spinDY: 0, kbT: 0,
    paws: 0, thinkT: (i * 7) % 12, ai: { tx: 0, ty: 0, wantCharge: 0 },
  };
}
function resetMatch() {
  cats = [mkCat(0, false), mkCat(1, true), mkCat(2, true), mkCat(3, true)];
  roundNum = 1; champ = -1; winner = -1;
  startRound();
}
function startRound() {
  const paws = cats.map(c => c.paws);
  cats = [mkCat(0, false), mkCat(1, true), mkCat(2, true), mkCat(3, true)];
  cats.forEach((c, i) => c.paws = paws[i]);
  parts = []; bursts = [];
  phase = 'countdown'; phaseT = 0;
}
function say(t, sub, dur) { announce = t; subAnnounce = sub || ''; announceT = dur || 90; }

function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }

/* ---------- combat ---------- */
function doShove(c, power) {
  c.pose = power > 0.55 ? 'stomp' : 'shove'; c.poseT = 12;
  c.shoveCD = 34; c.charging = false; c.chargeT = 0;
  SFX.thump(power);
  hitstop = 4;
  const hx = c.x + c.face * 26, hy = c.y - 6;
  bursts.push({ x: hx, y: hy, t: 0, big: power > 0.55 });
  for (let i = 0; i < 6 + power * 10; i++) {
    parts.push({ x: hx, y: hy, vx: (Math.random() - 0.5) * 5, vy: (Math.random() - 0.5) * 5, t: 22, c: '#ffd23e', s: 3 });
  }
  let hitAny = false;
  for (const o of cats) {
    if (o === c || !o.alive) continue;
    const dx = o.x - c.x, dy = o.y - c.y, d = Math.hypot(dx, dy) || 1;
    if (d < 58 && (dx * c.face) > -10) {
      const kb = (4.2 + power * 7.5) * (1 + o.wobble / 55);
      o.vx += dx / d * kb; o.vy += dy / d * kb;
      o.wobble = Math.min(100, o.wobble + 13 + power * 24);
      o.pose = 'hit'; o.poseT = 16; o.flash = 7; o.wobT = 40; o.kbT = 26;
      hitAny = true;
      SFX.hit();
    }
  }
  if (!hitAny) SFX.whiff();
}
function doSpin(c, dx, dy) {
  c.spinning = 13; c.spinCD = 55;
  const d = Math.hypot(dx, dy) || 1;
  c.spinDX = dx / d; c.spinDY = dy / d;
  if (Math.abs(dx) > 0.2) c.face = dx > 0 ? 1 : -1;
  c.pose = 'spin'; c.poseT = 13;
  SFX.dash();
  for (let i = 0; i < 8; i++) {
    parts.push({ x: c.x + (Math.random() - 0.5) * 20, y: c.y + 6 + (Math.random() - 0.5) * 8,
      vx: (Math.random() - 0.5) * 1.5, vy: -Math.random() * 1.2, t: 26, c: '#cbb89a', s: 3 });
  }
}
function ringOut(c) {
  c.alive = false; c.deadT = 0;
  SFX.whistle();
  for (let i = 0; i < 14; i++) {
    parts.push({ x: c.x, y: c.y, vx: (Math.random() - 0.5) * 3, vy: -Math.random() * 3, t: 30, c: '#ffffff', s: 2 });
  }
  say(c.name + ' IS OUT!', '', 80);
}

/* ---------- bot AI ---------- */
function botThink(c) {
  // find nearest living opponent
  let best = null, bd = 1e9;
  for (const o of cats) {
    if (o === c || !o.alive) continue;
    const d = dist(c.x, c.y, o.x, o.y);
    if (d < bd) { bd = d; best = o; }
  }
  const dc = dist(c.x, c.y, RING.x, RING.y);
  let dx = 0, dy = 0;
  if (best) {
    dx = best.x - c.x; dy = best.y - c.y;
    const d = Math.hypot(dx, dy) || 1; dx /= d; dy /= d;
  }
  // edge fear: steer to center when near rim
  if (dc > RING.r * 0.62) {
    const ix = (RING.x - c.x), iy = (RING.y - c.y);
    const d = Math.hypot(ix, iy) || 1;
    const w = Math.min(1, (dc - RING.r * 0.62) / (RING.r * 0.3));
    dx = dx * (1 - w) + (ix / d) * w * 1.6;
    dy = dy * (1 - w) + (iy / d) * w * 1.6;
  }
  // don't charge off the edge: if moving outward near rim, kill outward component
  const nx = c.x + dx * 10, ny = c.y + dy * 10;
  if (dist(nx, ny, RING.x, RING.y) > RING.r * 0.97) {
    const ix = RING.x - c.x, iy = RING.y - c.y, d = Math.hypot(ix, iy) || 1;
    dx = ix / d; dy = iy / d;
  }
  c.ai.tx = dx; c.ai.ty = dy;
  // attack decisions
  if (best && bd < 52 && c.shoveCD <= 0 && !c.charging && Math.random() < 0.5) {
    c.charging = true; c.chargeT = 0;
    c.ai.wantCharge = 14 + Math.random() * 22; // release threshold
  }
  if (c.charging) {
    c.chargeT++;
    if (c.face === 0) c.face = 1;
    // face the target while charging
    if (best) c.face = best.x >= c.x ? 1 : -1;
    if (c.chargeT >= c.ai.wantCharge || bd > 70) {
      doShove(c, Math.min(1, c.chargeT / 36));
    }
  }
  // spin when target is mid-range and cooldown ready
  if (best && bd > 70 && bd < 150 && c.spinCD <= 0 && Math.random() < 0.06) {
    doSpin(c, best.x - c.x, best.y - c.y);
  }
}

/* ---------- update ---------- */
function updateCat(c) {
  if (!c.alive) { c.deadT++; return; }
  if (c.flash > 0) c.flash--;
  if (c.poseT > 0) c.poseT--;
  if (c.wobT > 0) c.wobT--;
  if (c.shoveCD > 0) c.shoveCD--;
  if (c.spinCD > 0) c.spinCD--;
  if (c.kbT > 0) c.kbT--;
  c.wobble = Math.max(0, c.wobble - (c.wobT > 0 ? 0.04 : 0.22));

  let mx = 0, my = 0, wantShove = false, wantSpin = false, spinDx = c.face, spinDy = 0;
  if (c.bot) {
    if (c.thinkT-- <= 0) { c.thinkT = 10; botThink(c); }
    mx = c.ai.tx; my = c.ai.ty;
  } else {
    if (inLeft()) mx -= 1;
    if (inRight()) mx += 1;
    if (inUp()) my -= 1;
    if (inDown()) my += 1;
    const d = Math.hypot(mx, my);
    if (d > 1) { mx /= d; my /= d; }
    // shove charge on hold
    if (inShove() && c.shoveCD <= 0 && !c.charging) { c.charging = true; c.chargeT = 0; }
    if (c.charging) {
      c.chargeT++;
      if (mx !== 0) c.face = mx > 0 ? 1 : -1;
      if (!inShove()) doShove(c, Math.min(1, c.chargeT / 36));
      mx *= 0.25; my *= 0.25; // slow while charging
    }
    if (inSpin() && !c._spinHeld && c.spinCD <= 0 && !c.spinning) {
      wantSpin = true; spinDx = mx || c.face; spinDy = my;
    }
    c._spinHeld = inSpin();
  }

  // spin dash state
  if (c.spinning > 0) {
    c.spinning--;
    c.vx = c.spinDX * 6.4; c.vy = c.spinDY * 6.4;
    if (c.spinning % 3 === 0) {
      parts.push({ x: c.x, y: c.y + 8, vx: (Math.random() - 0.5), vy: -Math.random(), t: 20, c: '#cbb89a', s: 3 });
    }
    // spin contact knockback
    for (const o of cats) {
      if (o === c || !o.alive || o._spinHit) continue;
      if (dist(c.x, c.y, o.x, o.y) < CAT_R * 2 + 4) {
        o._spinHit = true;
        const dx = o.x - c.x, dy = o.y - c.y, d = Math.hypot(dx, dy) || 1;
        const kb = 5.2 * (1 + o.wobble / 60);
        o.vx += dx / d * kb; o.vy += dy / d * kb;
        o.wobble = Math.min(100, o.wobble + 12);
        o.pose = 'hit'; o.poseT = 14; o.flash = 6; o.wobT = 40; o.kbT = 22;
        SFX.hit(); hitstop = 4;
        bursts.push({ x: o.x, y: o.y - 8, t: 0, big: false });
      }
    }
  } else {
    const ACC = 0.55, MAXV = 2.5;
    const kb = c.kbT > 0;
    const damp = kb ? 0.35 : 1; // knocked cats can't steer much
    c.vx += mx * ACC * damp; c.vy += my * ACC * damp;
    if (!kb) {
      const sp = Math.hypot(c.vx, c.vy), max = MAXV + (c.charging ? -1.2 : 0);
      if (sp > Math.max(0.8, max)) { c.vx = c.vx / sp * Math.max(0.8, max); c.vy = c.vy / sp * Math.max(0.8, max); }
    }
    c.vx *= 0.94; c.vy *= 0.94;
    if (mx !== 0 && !c.charging) c.face = mx > 0 ? 1 : -1;
  }
  if (wantSpin) doSpin(c, spinDx, spinDy);

  c.x += c.vx; c.y += c.vy;
  for (const o of cats) o._spinHit = false;

  // pose selection
  if (c.poseT <= 0) {
    if (c.wobble > 62) c.pose = 'dizzy';
    else if (c.charging) c.pose = 'charge';
    else if (Math.hypot(c.vx, c.vy) > 0.5) c.pose = 'ready';
    else c.pose = 'ready';
  }

  // ring out?
  if (dist(c.x, c.y, RING.x, RING.y) > RING.r + 4) ringOut(c);
}

function update() {
  if (announceT > 0) announceT--;
  // particles
  for (let i = parts.length - 1; i >= 0; i--) {
    const p = parts[i];
    p.x += p.vx; p.y += p.vy; p.vy += 0.08; p.t--;
    if (p.t <= 0) parts.splice(i, 1);
  }
  for (let i = bursts.length - 1; i >= 0; i--) {
    bursts[i].t++;
    if (bursts[i].t > 14) bursts.splice(i, 1);
  }

  if (phase === 'title') {
    if (phaseT++ === 1) say('SUMO CAT!', AUTO ? 'auto demo — sit back' : 'Z = shove (hold to charge)   X = spin', 1e9);
    if (!AUTO && (inShove() || inSpin()) && phaseT > 30) { resetMatch(); SFX.go(); }
    if (AUTO && phaseT > 90) { resetMatch(); }
    return;
  }
  if (phase === 'countdown') {
    phaseT++;
    if (phaseT === 1) { say('ROUND ' + roundNum, '', 60); SFX.countTick(); }
    if (phaseT === 62) { say('FIGHT!', '', 45); SFX.go(); }
    if (phaseT > 100) { phase = 'fight'; phaseT = 0; }
    return;
  }
  if (phase === 'fight') {
    phaseT++;
    for (const c of cats) updateCat(c);
    const alive = cats.filter(c => c.alive);
    if (alive.length <= 1) {
      phase = 'roundEnd'; phaseT = 0;
      if (alive.length === 1) {
        winner = alive[0].idx;
        cats[winner].paws++;
        cats[winner].pose = 'victory'; cats[winner].poseT = 1e9;
        say(cats[winner].name + ' TAKES ROUND ' + roundNum + '!', '', 110);
        SFX.cheer();
        if (cats[winner].paws >= WIN_PAWS) { champ = winner; }
      } else {
        winner = -1;
        say('DOUBLE RING-OUT!', 'no paw awarded', 110);
      }
    }
    return;
  }
  if (phase === 'roundEnd') {
    for (const c of cats) if (c.alive) { c.vx *= 0.9; c.vy *= 0.9; c.x += c.vx; c.y += c.vy; }
    if (phaseT++ > 150) {
      if (champ >= 0) {
        phase = 'matchEnd'; phaseT = 0;
        say(cats[champ].name + ' IS CHAMPION!', 'first to ' + WIN_PAWS + ' paws', 1e9);
        SFX.cheer();
      } else {
        if (winner === -1) { /* replay same round number */ }
        else roundNum++;
        startRound();
      }
    }
    return;
  }
  if (phase === 'matchEnd') {
    phaseT++;
    if (cats[champ] && cats[champ].alive) { /* keep victory pose */ }
    if (phaseT > 420) {
      if (AUTO) { resetMatch(); }
      else if (inShove() || inSpin()) { resetMatch(); SFX.go(); }
      else if (phaseT === 421) say(cats[champ].name + ' IS CHAMPION!', 'press Z for rematch', 1e9);
    }
    return;
  }
}

/* ---------- render ---------- */
function drawTawara() {
  // straw bale ring border
  const n = 26;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const x = RING.x + Math.cos(a) * RING.r, y = RING.y + Math.sin(a) * RING.r;
    ctx.save();
    ctx.translate(x, y); ctx.rotate(a + Math.PI / 2);
    ctx.fillStyle = '#c9a227';
    ctx.fillRect(-7, -4, 14, 8);
    ctx.fillStyle = '#8a6d1a';
    ctx.fillRect(-7, 2, 14, 2);
    ctx.fillStyle = '#e8c84a';
    ctx.fillRect(-7, -4, 14, 2);
    ctx.restore();
  }
}
function drawPaw(x, y, s, col) {
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.ellipse(x, y + 2, 5 * s, 4 * s, 0, 0, 7); ctx.fill();
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath(); ctx.arc(x + i * 5 * s, y - 4 * s, 2.4 * s, 0, 7); ctx.fill();
  }
}
function drawCat(c) {
  const s = 0.42; // sprite ~260px -> ~110px tall on screen... too big; use 0.30
  const sc = 0.30;
  const flip = c.face < 0;
  // shadow
  const dc = dist(c.x, c.y, RING.x, RING.y);
  if (c.alive) {
    ctx.fillStyle = 'rgba(0,0,0,0.30)';
    ctx.beginPath(); ctx.ellipse(c.x, c.y + 22, 16, 5, 0, 0, 7); ctx.fill();
  } else {
    // falling out: shrink + fade
    const k = Math.max(0, 1 - c.deadT / 30);
    if (k <= 0) return;
    ctx.save(); ctx.globalAlpha = k;
    drawPose(ctx, 'hit', c.x, c.y - c.deadT * 1.5, flip, c.idx, sc * k);
    ctx.restore();
    return;
  }
  let alpha = 1;
  if (c.flash > 0 && (c.flash % 2 === 0)) alpha = 0.45;
  ctx.save(); ctx.globalAlpha = alpha;
  drawPose(ctx, c.pose, c.x, c.y, flip, c.idx, sc);
  ctx.restore();
  // dizzy stars
  if (c.pose === 'dizzy' || c.wobble > 62) {
    const t = Date.now() / 240;
    ctx.fillStyle = '#ffe14d';
    for (let i = 0; i < 3; i++) {
      const a = t + i * 2.09;
      const sx = c.x + Math.cos(a) * 20, sy = c.y - 52 + Math.sin(a) * 5;
      ctx.fillRect(sx - 1, sy - 4, 3, 9);
      ctx.fillRect(sx - 4, sy - 1, 9, 3);
    }
  }
  // charge indicator
  if (c.charging) {
    const p = Math.min(1, c.chargeT / 36);
    ctx.fillStyle = 'rgba(0,0,0,0.45)';
    ctx.fillRect(c.x - 20, c.y - 62, 40, 6);
    ctx.fillStyle = p > 0.55 ? '#ff5030' : '#ffd23e';
    ctx.fillRect(c.x - 19, c.y - 61, 38 * p, 4);
  }
  // name + wobble pip for player
  if (c.idx === 0 && !AUTO) {
    ctx.fillStyle = '#fff'; ctx.font = 'bold 9px monospace'; ctx.textAlign = 'center';
    ctx.fillText('YOU', c.x, c.y - 66);
  }
}
function drawBursts() {
  for (const b of bursts) {
    const t = b.t, R0 = 6 + t * (b.big ? 5 : 3.4);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = b.big ? 5 : 3;
    const n = 10;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + t * 0.12;
      ctx.beginPath();
      ctx.moveTo(b.x + Math.cos(a) * R0 * 0.45, b.y + Math.sin(a) * R0 * 0.45);
      ctx.lineTo(b.x + Math.cos(a) * R0, b.y + Math.sin(a) * R0);
      ctx.stroke();
    }
    if (b.big) {
      ctx.fillStyle = 'rgba(255,210,62,0.5)';
      ctx.beginPath(); ctx.arc(b.x, b.y, R0 * 0.7, 0, 7); ctx.fill();
    }
  }
}
function render() {
  // bg
  if (bgImg && bgImg.width) ctx.drawImage(bgImg, 0, 0, W, H);
  else { ctx.fillStyle = '#141422'; ctx.fillRect(0, 0, W, H); }
  // darken edges for readability
  const vg = ctx.createRadialGradient(RING.x, RING.y, 60, RING.x, RING.y, 220);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.45)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, W, H);

  drawTawara();

  // cats sorted by y
  const order = [...cats].sort((a, b) => a.y - b.y);
  for (const c of order) drawCat(c);
  drawBursts();

  // particles
  for (const p of parts) {
    ctx.globalAlpha = Math.min(1, p.t / 12);
    ctx.fillStyle = p.c;
    ctx.fillRect(p.x - p.s / 2, p.y - p.s / 2, p.s, p.s);
  }
  ctx.globalAlpha = 1;

  // HUD
  ctx.textAlign = 'left'; ctx.font = 'bold 11px monospace';
  ctx.fillStyle = '#ffd23e';
  ctx.fillText('ROUND ' + roundNum, 10, 18);
  // paws per cat
  const cols = ['#ffb14d', '#cfd6dd', '#b06a3b', '#ffe9a8'];
  cats.forEach((c, i) => {
    const y = 30 + i * 20;
    ctx.fillStyle = cols[i]; ctx.font = 'bold 10px monospace';
    ctx.fillText(c.name, 10, y + 4);
    for (let p = 0; p < WIN_PAWS; p++) {
      drawPaw(64 + p * 20, y, 0.9, p < c.paws ? '#ffd23e' : 'rgba(255,255,255,0.18)');
    }
  });
  // player wobble meter
  const me = cats[0];
  if (me && (phase === 'fight')) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)'; ctx.fillRect(10, H - 20, 120, 10);
    ctx.fillStyle = me.wobble > 62 ? '#ff4030' : me.wobble > 30 ? '#ffb130' : '#50d050';
    ctx.fillRect(12, H - 18, 116 * (me.wobble / 100), 6);
    ctx.fillStyle = '#fff'; ctx.font = 'bold 9px monospace';
    ctx.fillText('WOBBLE', 136, H - 11);
  }
  // announcements
  if (announceT > 0) {
    const a = Math.min(1, announceT / 20);
    ctx.save(); ctx.globalAlpha = Math.min(1, a + 0.2);
    ctx.textAlign = 'center';
    ctx.font = 'bold 30px monospace';
    ctx.fillStyle = '#14101f';
    ctx.fillText(announce, W / 2 + 2, 82);
    ctx.fillStyle = '#ffd23e';
    ctx.fillText(announce, W / 2, 80);
    if (subAnnounce) {
      ctx.font = 'bold 12px monospace';
      ctx.fillStyle = '#fff';
      ctx.fillText(subAnnounce, W / 2, 102);
    }
    ctx.restore();
  }
  if (phase === 'title') {
    ctx.textAlign = 'center'; ctx.font = 'bold 11px monospace'; ctx.fillStyle = '#8f96a8';
    ctx.fillText(AUTO ? '' : 'last cat on the dohyo wins the round', W / 2, H - 14);
  }
}

/* ---------- main loop ---------- */
let last = 0;
function frame(ts) {
  requestAnimationFrame(frame);
  if (hitstop > 0) { hitstop--; render(); return; } // freeze updates, keep rendering
  update();
  render();
}
loadAssets().then(() => {
  resetMatch();
  phase = 'title'; phaseT = 0; // show title first
  requestAnimationFrame(frame);
});
